from openpyxl import load_workbook

wb = load_workbook('budget.xlsx', data_only=False)
print("Sheets:", wb.sheetnames)
for name in wb.sheetnames:
    ws = wb[name]
    print(f"\n=== Sheet: {name} ({ws.max_row} rows x {ws.max_column} cols) ===")
    for row in ws.iter_rows():
        for cell in row:
            if cell.value is not None:
                print(f"{cell.coordinate}: {cell.value!r}")

import zipfile, re
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

with zipfile.ZipFile('budget.xlsx') as z:
    print("Archive entries:", [n for n in z.namelist() if not n.startswith('_rels') and 'rels' not in n])
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = [(s.get('name'), s.get('sheetId'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'))
              for s in wb.find('m:sheets', NS)]
    print("Sheets:", sheets)

    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    relmap = {r.get('Id'): r.get('Target') for r in rels}

    try:
        ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
        strings = [''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')) for si in ss]
    except KeyError:
        strings = []

    for name, sid, rid in sheets:
        target = relmap[rid]
        if not target.startswith('xl/'):
            target = 'xl/' + target.lstrip('/')
        print(f"\n=== Sheet: {name} ===")
        ws = ET.fromstring(z.read(target))
        for row in ws.find('m:sheetData', NS):
            r = row.get('r')
            vals = []
            for c in row:
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                isel = c.find('m:is', NS)
                if t == 's' and v is not None:
                    val = strings[int(v.text)]
                elif t == 'inlineStr' and isel is not None:
                    val = ''.join(tt.text or '' for tt in isel.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
                elif v is not None:
                    val = v.text
                else:
                    val = ''
                vals.append(f"{ref}={val}")
            if vals:
                print(f"row {r}: " + ", ".join(vals))

